def compute(vars):
    shares = vars["v1"]
    fair_value_per_share = vars["v2"]
    total_fair_value = shares * fair_value_per_share

    return {
        "value": total_fair_value,
        "trace": {
            "shares": shares,
            "fair_value_per_share": fair_value_per_share,
            "total_fair_value": total_fair_value,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": "currency"
            }
        }
    }
